def even_odd_palindrome(n):
    # Initialize count of even and odd palindromes to 0
    count_even, count_odd = 0, 0

    # Iterate from 1 to n
    for i in range(1, n+1):
        # Check if the number is a palindrome
        if str(i) == str(i)[::-1]:
            # Increment count of even or odd palindromes
            if i % 2 == 0:
                count_even += 1
            else:
                count_odd += 1

    # Return tuple with count of even and odd palindromes
    return count_even, count_odd
